"""Complete the original 56-question stroke chapter."""
from create_stroke_localization import rows,q
from create_stroke import ICH,SAH,CVT,ref,finalize
RC=ref('Glucocorticoid-Associated Worsening in RCVS: Primary Cohort Study','https://doi.org/10.1212/WNL.0000000000003510')

q('A patient with long-standing hypertension has a deep putaminal hemorrhage. Which underlying arteriopathy is most typical?', 'Hypertension-related deep perforator arteriopathy',[
 ('Cerebral amyloid angiopathy as the classic deep-only pattern','CAA more characteristically produces lobar/cortical hemorrhagic markers.'),('A venous sinus thrombosis as the default explanation','Venous lesions often have a different distribution and require venous evidence.'),('An isolated extracranial carotid plaque','This does not directly explain a deep hemorrhage.')],
 'Hemorrhage location helps prioritize mechanism', '**Deep basal ganglia, thalamic, pontine and cerebellar hemorrhages commonly reflect small-vessel hypertensive injury.**', ['Atypical age, imaging or clinical features can justify vascular/structural investigation.','A history of hypertension does not prove every hemorrhage has the same cause.'], '**Treat the acute bleed and long-term vascular driver.**', ['Monitor expansion, pressure and neurological status.','Sustained blood-pressure control reduces recurrence risk.'], [['Deep hemorrhage','Perforator arteriopathy common'],['Lobar pattern','Consider other mechanisms'],['Prevention','Long-term pressure control']], [ICH], 'clinical_scenario')
q('An older adult has recurrent lobar hemorrhages, strictly lobar microbleeds and cortical superficial siderosis. Which disease is favored?', 'Cerebral amyloid angiopathy',[
 ('Pure hypertensive deep perforator disease','The strictly lobar/cortical pattern favors CAA.'),('Wilson disease','This is not the characteristic hemorrhagic MRI phenotype.'),('A single lacunar ischemic infarct','This does not explain the recurrent lobar hemorrhagic markers.')],
 'The distribution of blood products can identify a vessel pathology', '**CAA affects cortical and leptomeningeal vessels and increases lobar hemorrhage risk.**', ['Formal diagnostic criteria integrate age, imaging and exclusion of alternatives.','A biopsy is not required in every probable imaging-defined case.'], '**Antithrombotic decisions require careful individualized risk assessment.**', ['Balance the indication against recurrent ICH risk.','Do not apply an AF prevention rule without considering the hemorrhagic substrate.'], [['CAA','Lobar/cortical pattern'],['Hypertensive arteriopathy','Often deep pattern'],['Treatment tradeoff','Ischemic versus bleeding risk']], [ICH], 'clinical_scenario')
q('A patient has mild-to-moderate spontaneous ICH and initial SBP 180 mmHg. What pressure strategy is reasonable under AHA/ASA 2022?', 'Smoothly target around 140 mmHg and maintain roughly 130–150 mmHg, avoiding excessive reduction',[
 ('Rapidly reduce SBP to 90 mmHg in every case','This risks hypoperfusion.'),('Allow persistent SBP 240 mmHg without assessment','Severe hypertension can promote expansion.'),('Apply this exact target to every massive ICH or surgical scenario without qualification','The evidence and safety differ in severe presentations.')],
 'Control expansion risk without creating perfusion injury', '**The recommended selected-patient approach emphasizes early smooth, sustained control.**', ['A target below 130 can be harmful in the relevant mild/moderate setting.','Large severe ICH and other emergencies need individualized management.'], '**Avoid oscillation and abrupt overshoot.**', ['Use a monitored titratable regimen.','Assess the neurological response and systemic state.'], [['Selected mild/moderate ICH','Target about 140'],['Maintenance','About 130–150'],['Too low/abrupt','Potential harm']], [ICH], 'clinical_scenario')
q('A patient on warfarin has acute ICH with elevated INR. Which reversal strategy is preferred when available?', 'Four-factor prothrombin complex concentrate plus IV vitamin K',[
 ('Vitamin K alone while waiting many hours for effect','Immediate factor replacement is needed for rapid reversal.'),('Fresh frozen plasma as always superior to PCC for speed and volume','PCC reverses more rapidly with less volume in the relevant setting.'),('Protamine as the specific warfarin antidote','Protamine reverses heparin, not warfarin.')],
 'Reverse the active anticoagulant effect urgently', '**PCC supplies vitamin K-dependent factors and vitamin K sustains their endogenous recovery.**', ['Dose and monitoring follow the emergency protocol.','Stop the anticoagulant and assess other hemostatic issues.'], '**Do not delay reversal for a complete etiological work-up.**', ['Monitor INR response and hematoma status.','Later anticoagulation resumption is a separate individualized decision.'], [['PCC','Rapid factor replacement'],['Vitamin K','Sustains correction'],['Protamine','Different anticoagulant target']], [ICH], 'clinical_scenario')
q('Which specific reversal agent targets dabigatran in a patient with life-threatening intracranial bleeding?', 'Idarucizumab',[
 ('Protamine','This targets heparin.'),('Vitamin K','This reverses vitamin K antagonist effects, not dabigatran directly.'),('Tranexamic acid as a specific dabigatran-binding antidote','It is not the specific binding reversal agent.')],
 'Match the antidote to the anticoagulant', '**Idarucizumab binds dabigatran and reverses its anticoagulant effect.**', ['Timing, renal function and ongoing drug exposure inform monitoring.','Other DOACs require a different reversal strategy.'], '**Provide complete hemorrhage care.**', ['Reversal does not replace neurocritical and neurosurgical assessment.','Check for persistent or recurrent anticoagulant activity when clinically appropriate.'], [['Dabigatran','Idarucizumab'],['Heparin','Protamine'],['Warfarin','PCC plus vitamin K']], [ICH])
q('A patient taking aspirin has spontaneous ICH and is not planned for emergency surgery. What is the role of routine platelet transfusion?', 'Avoid routine transfusion because it can be harmful in this setting',[
 ('Give platelets to every aspirin-exposed ICH patient','This conflicts with the nonoperative evidence.'),('Transfuse solely to make aspirin disappear from the medication list','That is not a therapeutic endpoint.'),('The same rule necessarily applies unchanged to emergency neurosurgery or severe thrombocytopenia','Those contexts require separate assessment.')],
 'A plausible reversal concept can fail in outcome trials', '**Routine platelet replacement is not recommended for nonoperative aspirin-associated spontaneous ICH.**', ['Emergency surgery and a true platelet-count problem are different questions.','Other hemostatic therapies have their own evidence limitations.'], '**Treat based on the actual indication.**', ['Review imaging, platelet count and procedure plans.','Do not extrapolate from anticoagulant reversal to antiplatelet transfusion.'], [['Nonoperative aspirin ICH','Routine platelets harmful'],['Emergency surgery','Separate decision'],['Severe thrombocytopenia','Separate indication assessment']], [ICH], 'clinical_scenario')
q('A cerebellar ICH measures 18 mL and causes neurological deterioration with hydrocephalus. What is the recommended direction?', 'Urgent surgical evacuation assessment, with ventricular drainage when indicated',[
 ('Observation alone because posterior-fossa space is unlimited','The confined space creates brainstem and hydrocephalus risk.'),('Wait a week for every such hemorrhage to liquefy','Delay can be fatal.'),('Lumbar puncture as routine decompression','This is unsafe with obstructive posterior-fossa pressure dynamics.')],
 'Posterior-fossa mass effect can be rapidly lethal', '**Cerebellar volume at least 15 mL, deterioration, compression or obstructive hydrocephalus supports urgent surgery.**', ['The clinical and imaging findings are considered together.','An EVD decision does not eliminate the need to address the mass itself.'], '**Arrange neurosurgical care promptly.**', ['Protect airway and perfusion during transfer.','Do not apply a conservative supratentorial rule uncritically.'], [['Posterior-fossa bleed','Limited reserve for expansion'],['≥15 mL/deterioration','Surgical indication context'],['Hydrocephalus','CSF diversion assessment']], [ICH], 'clinical_scenario')
q('ICH extends into the ventricles and causes acute hydrocephalus with reduced consciousness. What intervention may reduce mortality?', 'External ventricular drainage',[
 ('Routine lumbar puncture without considering obstruction','This can be dangerous in obstructive hydrocephalus.'),('Corticosteroids as established hydrocephalus treatment','They do not drain obstructed CSF and are not routine ICH therapy.'),('No intervention until all intraventricular blood has cleared','Hydrocephalus can be immediately life-threatening.')],
 'Treat the secondary CSF-flow obstruction', '**Ventricular drainage is indicated when hydrocephalus contributes to impaired consciousness.**', ['Drain placement and monitoring require neurosurgical expertise.','The underlying hematoma and coagulopathy need parallel management.'], '**Do not assume every low conscious level has the same mechanism.**', ['Sedation, seizures and structural injury can coexist.','Repeat clinical and imaging assessment guides care.'], [['IVH','Can obstruct CSF flow'],['Hydrocephalus plus deterioration','EVD assessment'],['Parallel care','Hematoma and systemic management']], [ICH], 'clinical_scenario')
q('A patient presents 14 hours after thunderclap headache. CT is negative but SAH remains clinically concerning. What is the AHA/ASA diagnostic direction?', 'Lumbar puncture after appropriate safety assessment to investigate SAH',[
 ('A negative late CT excludes SAH with certainty','Sensitivity depends on timing and circumstances.'),('Diagnose migraine without further evaluation solely because examination is normal','A sentinel hemorrhage can have a normal examination.'),('Start anticoagulation before resolving the hemorrhage question','This can be hazardous.')],
 'The six-hour context cannot be applied to every negative scan', '**For presentation beyond six hours or with a new deficit, a negative CT can require LP when suspicion persists.**', ['Assess contraindications such as mass effect and relevant coagulopathy.','CSF interpretation and aneurysm imaging follow the diagnostic pathway.'], '**Consider other thunderclap causes too.**', ['Dissection, CVT and RCVS are important alternatives.','A negative first test is not the end of a high-risk evaluation.'], [['Early high-quality CT','Different rule-out context'],['Late negative CT with concern','LP assessment'],['Thunderclap differential','Broader vascular causes']], [SAH], 'clinical_scenario')
q('What is the role of early enteral nimodipine after aneurysmal SAH?', 'Reduce delayed cerebral ischemia and improve functional outcomes',[
 ('Directly seal the ruptured aneurysm','The aneurysm still requires clipping or endovascular treatment.'),('Act as a guaranteed angiographic vasospasm cure in every artery','Outcome benefit should not be reduced to a universal vessel-diameter claim.'),('Replace all monitoring because deterioration cannot occur','DCI and other complications remain possible.')],
 'A neurovascular preventive drug does not secure the bleeding source', '**Early enteral nimodipine is a core aSAH therapy.**', ['The common regimen is 60 mg every four hours for about 21 days, adjusted for tolerability and protocol.','Avoid hypotension and maintain appropriate dosing continuity when possible.'], '**Continue aneurysm and critical-care management.**', ['Hydrocephalus, rebleeding and DCI need surveillance.','Do not administer an oral formulation intravenously.'], [['Nimodipine','DCI/outcome benefit'],['Aneurysm treatment','Prevents rebleeding source'],['Monitoring','Still essential']], [SAH])
q('Once a ruptured aneurysm causing SAH is identified, what is the usual treatment-timing goal?', 'Secure it as early as feasible, preferably within 24 hours, using an expert selected endovascular or surgical approach',[
 ('Wait until day 21 in every patient','This leaves an avoidable rebleeding risk.'),('Nimodipine alone makes aneurysm treatment unnecessary','It does not seal the aneurysm.'),('Choose clipping or coiling without considering anatomy or expertise','Selection should be multidisciplinary and anatomy based.')],
 'Remove the rebleeding source promptly', '**Complete obliteration is the goal when feasible.**', ['Aneurysm morphology, location, age and clinical state influence technique.','Poor prognosis and complex anatomy can require individualized decisions.'], '**Stabilize without creating unnecessary delay.**', ['Blood pressure, airway and hydrocephalus care proceed in parallel.','A secure aneurysm changes later DCI-treatment options.'], [['Timing','Preferably within 24 hours'],['Technique','Expert anatomy-based selection'],['Goal','Prevent rebleeding']], [SAH])
q('Several days after aneurysm securing, a patient develops a new focal deficit from suspected DCI after competing causes are assessed. What management principle is appropriate?', 'Maintain euvolemia and consider induced blood-pressure elevation in a suitable symptomatic patient under neurocritical care',[
 ('Routine prophylactic hypervolemia for every SAH patient','This increases morbidity and is not the modern routine strategy.'),('Deliberately induce hypotension to narrow cerebral vessels','This can worsen ischemia.'),('Assume every new deficit is DCI without checking hydrocephalus, seizure or rebleeding','The differential still matters.')],
 'Treat symptomatic ischemia without reviving an indiscriminate triple-H protocol', '**Euvolemia is preferred to routine hypervolemia.**', ['Selected symptomatic patients may benefit from hemodynamic augmentation.','Refractory vasospasm can require endovascular therapy.'], '**Reassess the cause and response continuously.**', ['Imaging, EEG and other tests can identify alternatives.','Cardiac and pulmonary reserve constrain augmentation.'], [['Baseline volume','Euvolemia'],['Symptomatic selected DCI','BP augmentation consideration'],['Refractory disease','Expert endovascular options']], [SAH], 'clinical_scenario')
q('A postpartum patient has progressive headache, seizures and a hemorrhagic lesion crossing usual arterial territories. Which investigation is especially important?', 'CT venography or MR venography for cerebral venous thrombosis',[
 ('Only extracranial carotid ultrasound','This does not adequately evaluate the venous sinuses.'),('A normal noncontrast CT as definitive exclusion','CVT can require dedicated venous imaging.'),('A D-dimer alone as a universal rule-out test','Sensitivity depends on presentation and cannot replace imaging in a high-risk syndrome.')],
 'A venous stroke can be hemorrhagic and nonterritorial', '**Pregnancy/puerperium is a relevant thrombotic context.**', ['Raised intracranial pressure, focal deficits and seizures can coexist.','Brain MRI/CT assesses the parenchymal effect as well as the clot.'], '**Investigate and treat promptly.**', ['Assess thrombosis risks and complications.','A hemorrhagic appearance does not automatically imply an arterial-ICH treatment pathway.'], [['Headache/seizure postpartum','CVT concern'],['CTV/MRV','Venous diagnosis'],['Hemorrhagic lesion','Can reflect venous infarction']], [CVT], 'clinical_scenario')
q('A patient has confirmed CVT with a small hemorrhagic venous infarct and no separate major contraindication. What is the standard treatment principle?', 'Therapeutic anticoagulation is generally indicated despite the venous infarct hemorrhage',[
 ('Any intracranial blood permanently prohibits anticoagulation in CVT','This confuses venous infarct management with other hemorrhage settings.'),('Aspirin is always equivalent to therapeutic heparin','It is not the standard acute CVT treatment.'),('Routine systemic thrombolysis is first-line for every stable CVT','Endovascular escalation is reserved for selected deterioration/failure settings.')],
 'Treat the obstructed venous drainage that caused the hemorrhagic injury', '**Heparin-based anticoagulation limits propagation and supports recanalization.**', ['LMWH is often favored, with UFH useful in selected procedural/renal contexts.','Large mass effect or a surgical emergency requires coordinated planning.'], '**Escalate if neurological deterioration continues.**', ['Decompressive surgery or selected endovascular rescue may be necessary.','Later agent and duration depend on risk factors and the clinical pathway.'], [['Acute CVT','Therapeutic anticoagulation'],['Small venous hemorrhage','Not an automatic contraindication'],['Deterioration','Expert rescue assessment']], [CVT], 'clinical_scenario')
q('Recurrent thunderclap headaches follow a vasoactive-drug exposure. Angiography shows multifocal segmental narrowing that resolves on follow-up. Which syndrome is favored?', 'Reversible cerebral vasoconstriction syndrome',[
 ('Primary CNS vasculitis as an automatic diagnosis from any beading','Beading is not specific, and the recurrent thunderclap/reversible pattern favors RCVS.'),('An isolated lacunar infarct as the full explanation','This does not account for multifocal reversible arterial narrowing.'),('Myasthenia gravis','This does not produce the vascular headache syndrome.')],
 'Time course and reversibility distinguish a syndrome from one angiographic snapshot', '**RCVS commonly presents with recurrent thunderclap pain over days to weeks.**', ['Early imaging can be unrevealing before narrowing evolves.','Hemorrhage, infarction and PRES-like changes can complicate the course.'], '**Exclude aneurysmal SAH and other emergencies first.**', ['Review serotonergic, sympathomimetic and other vasoactive exposures.','Follow-up vascular imaging supports the reversible diagnosis.'], [['Headache','Recurrent thunderclap'],['Angiography','Multifocal narrowing'],['Course','Reversibility over weeks, typically within 3 months']], [RC])
q('RCVS is diagnosed after exclusion of relevant mimics. What is the correct glucocorticoid principle?', 'Avoid routine steroids; observational evidence links glucocorticoid exposure to clinical/radiological worsening',[
 ('Treat all RCVS with high-dose steroids as though proven CNS vasculitis','The diseases have different treatment implications.'),('An angiographic beaded appearance alone mandates immunosuppression','The finding is not disease specific.'),('A calcium-channel blocker guarantees prevention of every infarct','Symptom treatment does not establish such a guarantee.')],
 'Misclassification as vasculitis can create treatment harm', '**A primary cohort found an association between steroids and RCVS worsening; this is observational evidence, not a randomized efficacy trial.**', ['Remove triggers and manage pain/pressure through a specialist pathway.','Calcium-channel blockers may help symptoms but robust outcome evidence is limited.'], '**Keep the differential open if the course is atypical.**', ['Inflammatory CSF or progressive persistent vessel disease can suggest another process.','Do not use a therapeutic steroid trial casually to decide the diagnosis.'], [['RCVS','No routine steroids'],['CNS vasculitis','Different evaluation/treatment'],['Evidence limit','Observational harm signal']], [RC])

